		for _, want := range []string{
			"--archive", "--org", "--seq", "--end-seq", "--fingerprint",
			"informational only", "Example:", "darksafe review",
			"Exit codes",
		} {
			if !strings.Contains(out, want) {
				t.Fatalf("review help missing %q:\n%s", want, out)
